CREATE COLUMN TABLE "TEST_AP"."OCHP" ("AbsEntry" INTEGER CS_INT NOT NULL , "Chapter" NVARCHAR(20), "Heading" NVARCHAR(20), "SubHeading" NVARCHAR(20), "Dscription" NVARCHAR(120), "ChapterID" NVARCHAR(64) NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OCHP" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$Chapter$Heading$SubHeading$','Chapter','Heading','SubHeading'));
CREATE UNIQUE INDEX "OCHP_CHAPTERID" ON "TEST_AP"."OCHP" ( "ChapterID" ASC );
CREATE INDEX "OCHP_CHAPTER" ON "TEST_AP"."OCHP" ( "Chapter" ASC, "Heading" ASC, "SubHeading" ASC )